            || (y == 2017 && d == 2 && m == 1)
            || (y == 2018 && d == 1 && m == 1)
            || (y == 2018 && d == 31 && m == 12)
            || (y == 2019 && d == 1 && m == 1)
            || (y == 2020 && d == 1 && m == 1)
            || (y == 2021 && d == 1 && m == 1)
            || (y == 2022 && d == 3 && m == 1)
            || (y == 2023 && d == 2 && m == 1)
            || (y == 2026 && (d == 1 || d == 2) && m == 1)
            // Chinese New Year
            || (y == 2004 && d >= 19 && d <= 28 && m == 1)
            || (y == 2005 && d >=  7 && d <= 15 && m == 2)
            || (y == 2006 && ((d >= 26 && m == 1) ||
                              (d <= 3 && m == 2)))
            || (y == 2007 && d >= 17 && d <= 25 && m == 2)
            || (y == 2008 && d >= 6 && d <= 12 && m == 2)
            || (y == 2009 && d >= 26 && d <= 30 && m == 1)
            || (y == 2010 && d >= 15 && d <= 19 && m == 2)
            || (y == 2011 && d >= 2 && d <= 8 && m == 2)
            || (y == 2012 && d >= 23 && d <= 28 && m == 1)
            || (y == 2013 && d >= 11 && d <= 15 && m == 2)
            || (y == 2014 && d >= 31 && m == 1)
            || (y == 2014 && d <= 6 && m == 2)
            || (y == 2015 && d >= 18 && d <= 24 && m == 2)
            || (y == 2016 && d >= 8 && d <= 12 && m == 2)
            || (y == 2017 && ((d >= 27 && m == 1) ||
                              (d <= 2 && m == 2)))
            || (y == 2018 && (d >= 15 && d <= 21 && m == 2))
            || (y == 2019 && d >= 4 && d <= 8 && m == 2)
            || (y == 2020 && (d == 24 || (d >= 27 && d <= 31)) && m == 1)
            || (y == 2021 && (d == 11 || d == 12 || d == 15 || d == 16 || d == 17) && m == 2)
            || (y == 2022 && ((d == 31 && m == 1) || (d <= 4 && m == 2)))
            || (y == 2023 && d >= 23 && d <= 27 && m == 1)
            || (y == 2024 && (d == 9 || (d >= 12 && d <= 16)) && m == 2)
            || (y == 2025 && ((d >= 28 && d <= 31 && m == 1) || (d >= 3 && d <= 4 && m == 2)))
            || (y == 2026 && ((d >= 16 && d <= 20) || d == 23) && m == 2)
            // Ching Ming Festival
            || (y <= 2008 && d == 4 && m == 4)
            || (y == 2009 && d == 6 && m == 4)
            || (y == 2010 && d == 5 && m == 4)
            || (y == 2011 && d >=3 && d <= 5 && m == 4)
            || (y == 2012 && d >= 2 && d <= 4 && m == 4)
            || (y == 2013 && d >= 4 && d <= 5 && m == 4)
            || (y == 2014 && d == 7 && m == 4)
            || (y == 2015 && d >= 5 && d <= 6 && m == 4)
            || (y == 2016 && d == 4 && m == 4)
            || (y == 2017 && d >= 3 && d <= 4 && m == 4)
            || (y == 2018 && d >= 5 && d <= 6 && m == 4)
            || (y == 2019 && d == 5 && m == 4)
            || (y == 2020 && d == 6 && m == 4)
            || (y == 2021 && d == 5 && m == 4)
            || (y == 2022 && d >= 4 && d <= 5 && m == 4)
            || (y == 2023 && d == 5 && m == 4)
            || (y == 2024 && d >= 4 && d <= 5 && m == 4)
            || (y == 2025 && d == 4 && m == 4)
            || (y == 2026 && d == 6 && m == 4)
            // Labor Day
            || (y <= 2007 && d >= 1 && d <= 7 && m == 5)
            || (y == 2008 && d >= 1 && d <= 2 && m == 5)
            || (y == 2009 && d == 1 && m == 5)
            || (y == 2010 && d == 3 && m == 5)
            || (y == 2011 && d == 2 && m == 5)
            || (y == 2012 && ((d == 30 && m == 4) ||
                              (d == 1 && m == 5)))
            || (y == 2013 && ((d >= 29 && m == 4) ||
                              (d == 1 && m == 5)))
            || (y == 2014 && d >= 1 && d <=3 && m == 5)
            || (y == 2015 && d == 1 && m == 5)
            || (y == 2016 && d >= 1 && d <=2 && m == 5)
            || (y == 2017 && d == 1 && m == 5)
            || (y == 2018 && ((d == 30 && m == 4) || (d == 1 && m == 5)))
            || (y == 2019 && d >= 1 && d <=3 && m == 5)
            || (y == 2020 && (d == 1 || d == 4 || d == 5) && m == 5)
            || (y == 2021 && (d == 3 || d == 4 || d == 5) && m == 5)
            || (y == 2022 && d >= 2 && d <= 4 && m == 5)
            || (y == 2023 && d >= 1 && d <= 3 && m == 5)
            || (y == 2024 && d >= 1 && d <= 3 && m == 5)
            || (y == 2025 && (d == 1 || d == 2 || d == 5) && m == 5)
            || (y == 2026 && (d == 1 || d == 4 || d == 5) && m == 5)
            // Tuen Ng Festival
            || (y <= 2008 && d == 9 && m == 6)
            || (y == 2009 && (d == 28 || d == 29) && m == 5)
