            || (y == 2020 && d >= 25 && d <= 26 && m == 6)
            || (y == 2021 && d == 14 && m == 6)
            || (y == 2022 && d == 3 && m == 6)
            || (y == 2023 && d >= 22 && d <= 23 && m == 6)
            || (y == 2024 && d == 10 && m == 6)
            || (y == 2025 && d == 2 && m == 6)
            || (y == 2026 && d == 19 && m == 6)
            // Mid-Autumn Festival
            || (y <= 2008 && d == 15 && m == 9)
            || (y == 2010 && d >= 22 && d <= 24 && m == 9)
            || (y == 2011 && d >= 10 && d <= 12 && m == 9)
            || (y == 2012 && d == 30 && m == 9)
            || (y == 2013 && d >= 19 && d <= 20 && m == 9)
            || (y == 2014 && d == 8 && m == 9)
