            || (y == 2016 && d >= 15 && d <= 16 && m == 9)
            || (y == 2018 && d == 24 && m == 9)
            || (y == 2019 && d == 13 && m == 9)
            || (y == 2021 && (d == 20 || d == 21) && m == 9)
            || (y == 2022 && d == 12 && m == 9)
            || (y == 2023 && d == 29 && m == 9)
            || (y == 2024 && d >= 16 && d <= 17 && m == 9)
            || (y == 2026 && d == 25 && m == 9)
            // National Day
            || (y <= 2007 && d >= 1 && d <= 7 && m == 10) 
            || (y == 2008 && ((d >= 29 && m == 9) ||
                              (d <= 3 && m == 10)))
            || (y == 2009 && d >= 1 && d <= 8 && m == 10)
            || (y == 2010 && d >= 1 && d <= 7 && m == 10)
            || (y == 2011 && d >= 1 && d <= 7 && m == 10)
            || (y == 2012 && d >= 1 && d <= 7 && m == 10)
            || (y == 2013 && d >= 1 && d <= 7 && m == 10)
            || (y == 2014 && d >= 1 && d <= 7 && m == 10)
            || (y == 2015 && d >= 1 && d <= 7 && m == 10)
