pub(in crate::time::calendar) fn new_zealand_common(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day (possibly moved to Monday or Tuesday)
            || ((d == 1 || (d == 3 && (w == Monday || w == Tuesday))) &&
                m == 1)
            // Day after New Year's Day (possibly moved to Mon or Tuesday)
            || ((d == 2 || (d == 4 && (w == Monday || w == Tuesday))) &&
                m == 1)
            // Waitangi Day. February 6th (possibly moved to Monday since 2013)
            || (d == 6 && m == 2)
            || ((d == 7 || d == 8) && w == Monday && m == 2 && y > 2013)
            // Good Friday
            || (dd == em-3)
            // Easter Monday
            || (dd == em)
            // ANZAC Day. April 25th (possibly moved to Monday since 2013) 
            || (d == 25 && m == 4)
            || ((d == 26 || d == 27) && w == Monday && m == 4 && y > 2013)
            // Queen's Birthday, first Monday in June
            || (d <= 7 && w == Monday && m == 6)
            // Labour Day, fourth Monday in October
            || ((d >= 22 && d <= 28) && w == Monday && m == 10)
            // Christmas, December 25th (possibly Monday or Tuesday)
            || ((d == 25 || (d == 27 && (w == Monday || w == Tuesday)))
                && m == 12)
            // Boxing Day, December 26th (possibly Monday or Tuesday)
            || ((d == 26 || (d == 28 && (w == Monday || w == Tuesday)))
                && m == 12)
            // Matariki, it happens on Friday in June or July
            // official calendar released by the NZ government for the
            // next 30 years
            || (d == 20 && m == 6 && y == 2025)
            || (d == 21 && m == 6 && (y == 2030 || y == 2052))
            || (d == 24 && m == 6 && (y == 2022 || y == 2033 || y == 2044))
            || (d == 25 && m == 6 && (y == 2027 || y == 2038 || y == 2049))
            || (d == 28 && m == 6 && y == 2024)
            || (d == 29 && m == 6 && (y == 2035 || y == 2046))
            || (d == 30 && m == 6 && y == 2051)
            || (d == 2  && m == 7 && y == 2032)
            || (d == 3  && m == 7 && (y == 2043 || y == 2048))
            || (d == 6  && m == 7 && (y == 2029 || y == 2040))
            || (d == 7  && m == 7 && (y == 2034 || y == 2045))
            || (d == 10 && m == 7 && (y == 2026 || y == 2037))
            || (d == 11 && m == 7 && (y == 2031 || y == 2042))
            || (d == 14 && m == 7 && (y == 2023 || y == 2028))
            || (d == 15 && m == 7 && (y == 2039 || y == 2050))
            || (d == 18 && m == 7 && y == 2036)
            || (d == 19 && m == 7 && (y == 2041 || y == 2047))
            // Queen Elizabeth's funeral
            || (d == 26 && m == 9 && y == 2022)
    {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn new_zealand_wellington(x: &Day) -> bool {
    let (d, m, w) = (x.d, x.m, x.w);
    if !new_zealand_common(x) {
        return false;
    }
    // Anniversary Day, Monday nearest January 22nd
    if (d >= 19 && d <= 25) && w == Monday && m == 1 {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn new_zealand_auckland(x: &Day) -> bool {
    let (d, m, w) = (x.d, x.m, x.w);
    if !new_zealand_common(x) {
        return false;
    }
    // Anniversary Day, Monday nearest January 29nd
    if (d >= 26 && w == Monday && m == 1) || (d == 1 && w == Monday && m == 2) {
        return false;
    }

    true
}

pub(in crate::time::calendar) fn singapore_sgx(x: &Day) -> bool {
    let (d, m, y, w, dd) = (x.d, x.m, x.y, x.w, x.dd);
    let em = easter_monday(y);
    if is_weekend(w)
            // New Year's Day
            || ((d == 1 || (d == 2 && w == Monday)) && m == 1)
            // Good Friday
            || (dd == em-3)
            // Labor Day
            || (d == 1 && m == 5)
            // National Day
            || ((d == 9 || (d == 10 && w == Monday)) && m == 8)
            // Christmas Day
            || (d == 25 && m == 12)

            // Chinese New Year
            || ((d == 22 || d == 23) && m == 1 && y == 2004)
            || ((d == 9 || d == 10) && m == 2 && y == 2005)
            || ((d == 30 || d == 31) && m == 1 && y == 2006)
            || ((d == 19 || d == 20) && m == 2 && y == 2007)
            || ((d == 7 || d == 8) && m == 2 && y == 2008)
            || ((d == 26 || d == 27) && m == 1 && y == 2009)
            || ((d == 15 || d == 16) && m == 1 && y == 2010)
            || ((d == 23 || d == 24) && m == 1 && y == 2012)
            || ((d == 11 || d == 12) && m == 2 && y == 2013)
            || (d == 31 && m == 1 && y == 2014)
            || (d == 1 && m == 2 && y == 2014)

            // Hari Raya Haji
            || ((d == 1 || d == 2) && m == 2 && y == 2004)
            || (d == 21 && m == 1 && y == 2005)
            || (d == 10 && m == 1 && y == 2006)
            || (d == 2 && m == 1 && y == 2007)
            || (d == 20 && m == 12 && y == 2007)
            || (d == 8 && m == 12 && y == 2008)
            || (d == 27 && m == 11 && y == 2009)
            || (d == 17 && m == 11 && y == 2010)
            || (d == 26 && m == 10 && y == 2012)
            || (d == 15 && m == 10 && y == 2013)
            || (d == 6 && m == 10 && y == 2014)

            // Vesak Poya Day
            || (d == 2 && m == 6 && y == 2004)
            || (d == 22 && m == 5 && y == 2005)
            || (d == 12 && m == 5 && y == 2006)
            || (d == 31 && m == 5 && y == 2007)
            || (d == 18 && m == 5 && y == 2008)
            || (d == 9 && m == 5 && y == 2009)
            || (d == 28 && m == 5 && y == 2010)
            || (d == 5 && m == 5 && y == 2012)
            || (d == 24 && m == 5 && y == 2013)
            || (d == 13 && m == 5 && y == 2014)

            // Deepavali
            || (d == 11 && m == 11 && y == 2004)
            || (d == 8 && m == 11 && y == 2007)
            || (d == 28 && m == 10 && y == 2008)
            || (d == 16 && m == 11 && y == 2009)
            || (d == 5 && m == 11 && y == 2010)
            || (d == 13 && m == 11 && y == 2012)
            || (d == 2 && m == 11 && y == 2013)
            || (d == 23 && m == 10 && y == 2014)

            // Diwali
            || (d == 1 && m == 11 && y == 2005)

            // Hari Raya Puasa
            || ((d == 14 || d == 15) && m == 11 && y == 2004)
            || (d == 3 && m == 11 && y == 2005)
            || (d == 24 && m == 10 && y == 2006)
            || (d == 13 && m == 10 && y == 2007)
            || (d == 1 && m == 10 && y == 2008)
            || (d == 21 && m == 9 && y == 2009)
            || (d == 10 && m == 9 && y == 2010)
            || (d == 20 && m == 8 && y == 2012)
            || (d == 8 && m == 8 && y == 2013)
            || (d == 28 && m == 7 && y == 2014)
    {
        return false;
    }

    // https://api2.sgx.com/sites/default/files/2019-01/2019%20DT%20Calendar.pdf
    if y == 2019 {
        if
        // Chinese New Year
        ((d == 5 || d == 6) && m == 2)
                // Vesak Poya Day
                || (d == 20 && m == 5)
                // Hari Raya Puasa
                || (d == 5 && m == 6)
                // Hari Raya Haji
                || (d == 12 && m == 8)
                // Deepavali
                || (d == 28 && m == 10)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2020-11/SGX%20Derivatives%20Trading%20Calendar%202020_Dec%20Update_D3.pdf
    if y == 2020 {
        if
        // Chinese New Year
        (d == 27 && m == 1)
                // Vesak Poya Day
                || (d == 7 && m == 5)
                // Hari Raya Puasa
                || (d == 25 && m == 5)
                // Hari Raya Haji
                || (d == 31 && m == 7)
                // Deepavali
                || (d == 14 && m == 11)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2021-07/SGX_Derivatives%20Trading%20Calendar%202021%20%28Final%20-%20Jul%29.pdf
    if y == 2021 {
        if
        // Chinese New Year
        (d == 12 && m == 2)
                // Hari Raya Puasa
                || (d == 13 && m == 5)
                // Vesak Poya Day
                || (d == 26 && m == 5)
                // Hari Raya Haji
                || (d == 20 && m == 7)
                // Deepavali
                || (d == 4 && m == 11)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2022-06/DT%20Trading%20Calendar%202022%20%28Final%29.pdf
    if y == 2022 {
        if
        // Chinese New Year
        ((d == 1 || d == 2) && m == 2)
                // Labour Day
                || (d == 2 && m == 5)
                // Hari Raya Puasa
                || (d == 3 && m == 5)
                // Vesak Poya Day
                || (d == 16 && m == 5)
                // Hari Raya Haji
                || (d == 11 && m == 7)
                // Deepavali
                || (d == 24 && m == 10)
                // Christmas Day
                || (d == 26 && m == 12)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2023-01/SGX%20Calendar%202023_0.pdf
    if y == 2023 {
        if
        // Chinese New Year
        ((d == 23 || d == 24) && m == 1)
                // Hari Raya Puasa
                || (d == 22 && m == 4)
                // Vesak Poya Day
                || (d == 2 && m == 6)
                // Hari Raya Haji
                || (d == 29 && m == 6)
                // Public holiday on polling day
                || (d == 1 && m == 9)
                // Deepavali
                || (d == 13 && m == 11)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2024-01/SGX%20Calendar%202024_2.pdf
    if y == 2024 {
        if
        // Chinese New Year
        (d == 12 && m == 2)
                // Hari Raya Puasa
                || (d == 10 && m == 4)
                // Vesak Poya Day
                || (d == 22 && m == 5)
                // Hari Raya Haji
                || (d == 17 && m == 6)
                // Deepavali
                || (d == 31 && m == 10)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2025-07/DT%20Trading%20Calendar%202025%20%28updated%2031%20Jul%202025%29.pdf
    if y == 2025 {
        if
        // Chinese New Year
        ((d == 29 || d == 30) && m == 1)
                // Hari Raya Puasa
                || (d == 31 && m == 3)
                // Vesak Poya Day
                || (d == 12 && m == 5)
                // Deepavali
                || (d == 20 && m == 10)
        {
            return false;
        }
    }
    // https://api2.sgx.com/sites/default/files/2026-01/SGX%20Calendar%202026_2.pdf
    if y == 2026 {
        if
        // Chinese New Year
        ((d == 17 || d == 18) && m == 2)
                // Hari Raya Puasa
                || (d == 20 && m == 3)
                // Hari Raya Haji
                || (d == 27 && m == 5)
                // Vesak Day (Sunday May 31st, observed Monday June 1st)
                || (d == 1 && m == 6)
                // Deepavali (Sunday Nov 8th, observed Monday Nov 9th)
                || (d == 9 && m == 11)
        {
            return false;
        }
    }
    true
}

