pub(in crate::time::calendar) fn south_korea_krx(x: &Day) -> bool {
    let (d, m, y, w) = (x.d, x.m, x.y, x.w);
    // public holidays
    if !south_korea_settlement(x) {
        return false;
    }
    if
    // Year-end closing
    ((((d == 29 || d == 30) && w == Friday) || d == 31) && m == 12) {
        return false;
    }
    if
    // occasional closing days (KRX day)
    (d == 6 && m == 5 && y == 2016) || (d == 2 && m == 10 && y == 2017) {
        return false;
    }
    true
}

